@RestController
public class OrderController {

    private final OrderService orderService;

    @GetMapping("/orders/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        long start = System.currentTimeMillis();

        var order = orderService.findById(id);
        // If STW GC pause happens here, this thread freezes
        // User sees total latency = processing + GC pause time

        long duration = System.currentTimeMillis() - start;
        // duration includes any STW pause that occurred

        return ResponseEntity.ok(order);
    }

    // Enable GC logging to see pauses:
    // -Xlog:gc*:file=gc.log:time,uptime:filecount=5,filesize=100M
}
