@Service
public class ReportService {

    // Long-lived object, allocated once, lives in Old Gen
    private final ReportRepository repository;

    public Report generateReport(Long userId) {
        // Temporary objects allocated in Young Gen
        var userData = repository.findByUserId(userId);
        var builder = new StringBuilder();

        for (var record : userData) {
            // Lots of temporary String objects in Young Gen
            builder.append(record.toString()).append("\n");
        }

        // After multiple Minor GCs, if builder survives,
        // it gets promoted to Old Generation

        var finalReport = new Report(builder.toString());
        // If finalReport is returned and referenced long-term,
        // it eventually moves to Old Gen
        return finalReport;
    }
}
