@Service
public class BatchProcessor {

    // WRONG: Calling System.gc() manually
    public void processBatchWrong(List<Record> records) {
        for (var record : records) {
            processRecord(record);
        }

        System.gc(); // BAD: Don't do this
        // Forces Full GC, causes long pause, disrupts JVM heuristics
    }

    // CORRECT: Let JVM manage GC
    public void processBatchCorrect(List<Record> records) {
        for (var record : records) {
            processRecord(record);
        }

        // No manual GC call. JVM will collect when needed.
        // Properly tuned heap and GC settings handle this.
    }

    // Only acceptable use: testing or heap dump preparation
    void prepareHeapDump() {
        System.gc(); // Force collection before heap dump
        // Use with -XX:+DisableExplicitGC in production
    }
}
