// WRONG: Using finalize() (deprecated, unreliable)
public class DatabaseConnection {
    private Socket socket;

    @Override
    protected void finalize() throws Throwable {
        // BAD: May never run, runs at unpredictable time
        if (socket != null) {
            socket.close();
        }
        super.finalize();
    }
}

// CORRECT: Using AutoCloseable with try-with-resources
public class DatabaseConnection implements AutoCloseable {
    private Socket socket;

    @Override
    public void close() {
        // Runs immediately when leaving try block
        if (socket != null) {
            socket.close();
        }
    }

    // Usage:
    public void queryDatabase() {
        try (var conn = new DatabaseConnection()) {
            // Use connection
        } // close() called automatically here
    }
}
